-- ============================================================
-- CAPPTURE — PEP Click & Collect store locations (855 stores)
-- Source: pep_store_list_extracted.csv
-- Idempotent upsert keyed on store_code.
-- Apply after migration 037_pep_click_collect.sql.
-- ============================================================

begin;

on conflict (store_code) do update set
  store_name  = excluded.store_name,
  province    = excluded.province,
  city        = excluded.city,
  address_line= excluded.address_line,
  raw_address = excluded.raw_address;

commit;
